namespace="/display";var socket=io(namespace);$(document).ready(function(){socket.on("connect",function(){var con_stat=document.getElementById("con_status");con_stat.classList.remove("badge-danger");con_stat.classList.add("badge-success");socket.emit("async_mode")});socket.on("disconnect",function(){var con_stat=document.getElementById("con_status");con_stat.classList.remove("badge-success");con_stat.classList.add("badge-danger");$("#async_mode").text("NA");$("#ping_pong").text("NA ")});socket.on("con_request",function(msg,cb){if(cb){cb()}});socket.on("async_request",function(msg,cb){$("#async_mode").text(msg.data);if(cb){var response={client_id:socket.sid,data:msg.data};cb(client_id=socket.sid,data=msg.data)}});var ping_pong_times=[];var start_time;window.setInterval(function(){start_time=(new Date).getTime();socket.emit("my_ping")},1e3);socket.on("my_pong",function(){var latency=(new Date).getTime()-start_time;ping_pong_times.push(latency);ping_pong_times=ping_pong_times.slice(-30);var sum=0;for(var i=0;i<ping_pong_times.length;i++)sum+=ping_pong_times[i];$("#ping_pong").text(Math.round(10*sum/ping_pong_times.length)/10+" ")})});